<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/config.php';
require_once __DIR__ . '/../02_Gameplay/WorldService.php';
$pdo=db();$playerId=1;$world=new WorldService($pdo);
$beforeResources=(int)$pdo->query("SELECT naquadah FROM player_resources WHERE player_id={$playerId}")->fetchColumn();
$fixture=$pdo->query("SELECT m.id,m.planet_id,m.jump_gate_level FROM universe_moons m JOIN universe_planets p ON p.id=m.planet_id WHERE p.is_occupied=0 ORDER BY m.id LIMIT 1")->fetch(PDO::FETCH_ASSOC);if(!$fixture){fwrite(STDERR,"No unoccupied moon fixture available\n");exit(1);}$moonId=(int)$fixture['id'];$planetId=(int)$fixture['planet_id'];$beforeLevel=(int)$fixture['jump_gate_level'];$colonyId=null;
try{$pdo->prepare("INSERT INTO player_colonies(player_id,planet_id,colony_name,is_homeworld,population,food,water,morale,colony_level) VALUES(?,?,?,0,0,0,0,1.000,1)")->execute([$playerId,$planetId,'Moon Registry Contract Colony']);$colonyId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE universe_planets SET is_occupied=1 WHERE id=?')->execute([$planetId]);$snapshot=$world->moonRegistrySnapshot($playerId,$moonId);if($snapshot['state']!=='ready'||count($snapshot['moons'])<1)throw new RuntimeException('Moon snapshot not ready');$selected=$snapshot['selected'];$expected=round((float)$selected['orbital_class_factor']*(float)$selected['infrastructure_factor']*(float)$selected['gate_technology_factor'],3);if((float)$selected['moon_bonus']!==$expected)throw new RuntimeException('Moon bonus formula mismatch');if(!$selected['owned'])throw new RuntimeException('Temporary owned moon not marked owned');$result=$world->upgradeMoonGate($playerId,$moonId);$expectedCost=15000+($beforeLevel*10000);if((int)$result['cost']!==$expectedCost)throw new RuntimeException('Gate cost mismatch');$r=$pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=?');$r->execute([$playerId]);if((int)$r->fetchColumn()!==$beforeResources-$expectedCost)throw new RuntimeException('Resource debit mismatch');$m=$pdo->prepare('SELECT jump_gate_level FROM universe_moons WHERE id=?');$m->execute([$moonId]);if((int)$m->fetchColumn()!==$beforeLevel+1)throw new RuntimeException('Gate level was not persisted');$c=$pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='moon_gate_upgrade'");$c->execute([$playerId]);if(!$c->fetchColumn())throw new RuntimeException('Moon gate cooldown missing');echo "PASS: Moon Registry inspection, bonus, ownership, gate upgrade, resource debit, cooldown, and persistence verified\n";}finally{$pdo->prepare('UPDATE universe_moons SET jump_gate_level=? WHERE id=?')->execute([$beforeLevel,$moonId]);if($colonyId)$pdo->prepare('DELETE FROM player_colonies WHERE id=?')->execute([$colonyId]);$pdo->prepare('UPDATE universe_planets SET is_occupied=0 WHERE id=?')->execute([$planetId]);$pdo->prepare('UPDATE player_resources SET naquadah=? WHERE player_id=?')->execute([$beforeResources,$playerId]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='moon_gate_upgrade'")->execute([$playerId]);$pdo->prepare("DELETE FROM game_events WHERE player_id=? AND event_type='moon_gate_upgraded' AND JSON_EXTRACT(payload,'$.moon_id')=?")->execute([$playerId,$moonId]);}
